import{z as s,x as B,o as E,c as A,q as t,j as o,D as e,d as r,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"托宾 q","description":"","frontmatter":{"title":"托宾 q","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/tobin-q.md","filePath":"econ/tobin-q.md","lastUpdated":1791063341000}'),q={name:"econ/tobin-q.md"};function p(d,a,h,m,_,D){const i=B("Mermaid");return E(),A("div",null,[a[2]||(a[2]=t('<h1 id="托宾-q" tabindex="-1">托宾 q <a class="header-anchor" href="#托宾-q" aria-label="Permalink to &quot;托宾 q&quot;">​</a></h1><div class="epigraph"><p>多装一单位资本值多少，相对重置它要花多少：这个比大于一就投资，小于一就停——投资跟着边际 $q$，不是跟着当期利润的会计。</p><footer>—— Tobin, A General Equilibrium Approach to Monetary Theory, JMCB 1969；Hayashi 对平均 q 与边际 q 的对齐</footer></div><p><a href="/econ/efficiency-wage">上一课</a>在劳动侧留下均衡失业：工资可以钉在出清之上。资本侧若完全灵活，投资会跳到使 \\(K\\) 立刻到达合意水平，周期里的 \\(I\\) 不会缓慢。本课的缺口是给出投资的影子价格：Tobin 的 \\(q\\)。调整成本下一课才说这个 \\(q\\) 如何映射到<strong>有限的</strong> \\(I\\)；本课先钉边际 q 是什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>索洛把 \\(I=sY\\) 当储蓄率。厂商问题里，资本的影子价值 \\(\\lambda\\) 相对其重置价格 \\(P_K\\)，定义为边际</p> \\[q=\\frac{\\lambda}{P_K}. \\]<p>\\(q\\gt 1\\) 时多装资本的现值超过成本，应该投；\\(q\\lt 1\\) 则相反。缺口不是再写效率工资，而是：投资决策的充分统计是这个比，而不是当期会计利润或现金流本身。Hayashi（1982）：在线性齐次生产与线性齐次调整成本下，边际 \\(q\\) 等于可观测的平均 \\(Q=\\) 证券价值 / 资本重置成本。没有这条对齐，股市市值不能直接当投资回归的右侧。</p><p><span class="marginnote">数字实例：一家公司股票市值 12 亿元，厂房设备按今天的重置价算值 10 亿元，平均 \\(Q=1.2\\)，大于 1——按理论该多建产能；若市值跌到 9 亿元，\\(Q=0.9\\)，边际上扩产就不划算。</span></p><p><span class="marginnote">平均 \\(Q\\) 用的是企业证券的市场价值。那是宏观投资理论的可观测代理，不是量化栏的限价簿或 CAPM 实证。本课不估计 \\(\\beta\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>无摩擦、无调整成本时，\\(q\\) 被钉在 1，\\(K\\) 瞬时跳到合意——投资率可以无限。这正是下一课要关掉的刀刃。本课保留定义：\\(\\lambda\\) 来自资本的欧拉（未来边际产出与资本利得的贴现）。货币政策、需求、效率工资造成的就业，都通过未来利润进入 \\(\\lambda\\)，从而进入 \\(q\\)。托宾原初还把 \\(q\\) 接到货币与资产组合；宏观主干后来把它收成投资理论。</p>',11)),(E(),o(l,null,{default:e(()=>[n(i,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAM%5B%22%E8%B5%84%E6%9C%AC%E5%BD%B1%E5%AD%90%E4%BB%B7%E6%A0%BC%20%CE%BB%22%5D%20--%3E%20Q%5B%22%E8%BE%B9%E9%99%85%20q%20%3D%20%CE%BB%2FP_K%22%5D%0A%20%20Q%20--%3E%20INV%5B%22q%3E1%20%E2%87%92%20%E6%8A%95%E8%B5%84%22%5D%0A%20%20HAY%5B%22Hayashi%EF%BC%9A%E5%B9%B3%E5%9D%87%20Q%20%3D%20%E8%BE%B9%E9%99%85%20q%22%5D%20--%3E%20OBS%5B%22%E8%AF%81%E5%88%B8%E4%BB%B7%E5%80%BC%20%2F%20%E9%87%8D%E7%BD%AE%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>公司金融的 MM 说资本结构不改企业价值；这里的 \\(q\\) 是资产侧相对重置成本。税盾与代理会让平均 \\(Q\\) 偏离边际 \\(q\\)，那是后课与公司金融课的缺口，本课先取齐性基准。</p><h3 id="不是「股价涨就该投」的口号" tabindex="-1">不是「股价涨就该投」的口号 <a class="header-anchor" href="#不是「股价涨就该投」的口号" aria-label="Permalink to &quot;不是「股价涨就该投」的口号&quot;">​</a></h3><p>平均 \\(Q\\) 含泡沫、风险溢价与无形资产测量误差。\\(q\\) 理论说的是<strong>边际</strong>影子价值；用市值当代理要声明 Hayashi 条件是否近似成立。把 \\(q\\) 回归的拟合优度当成理论真伪，是把测量当结构。</p><h3 id="不是股价预测作业" tabindex="-1">\\(q\\) 不是股价预测作业 <a class="header-anchor" href="#不是股价预测作业" aria-label="Permalink to &quot;$q$ 不是股价预测作业&quot;">​</a></h3><p>边际 \\(q\\) 是资本欧拉的影子价格。把指数点位当 \\(q\\)，已经把风险溢价、泡沫与现金资产混进重置成本比。</p><p>本课只要求投资理论用 \\(q\\) 当充分统计；预测股价不是宏观主干。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>预期未来的边际产出上升（技术、需求、更低的折扣率），\\(\\lambda\\) 升，\\(q\\) 升，投资意愿升。重置成本 \\(P_K\\) 升则 \\(q\\) 降——同样的影子价值，装机更贵。效率工资提高劳动成本，可以压低资本的未来租，从而压 \\(q\\)；通道是利润，不是把纪律工资写成投资函数的自变量。</p><p><span class="marginnote">术语翻译：「影子价格 \\(\\lambda\\)」就是多装一单位资本能给未来利润带来的现值增量——它不是货架上标价出售的东西，而是从最优化的一阶条件里「算出来」的内在价值。</span></p>',9)),(E(),o(l,null,{default:e(()=>[n(i,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20MPK%5B%22%E9%A2%84%E6%9C%9F%E6%9C%AA%E6%9D%A5%E8%BE%B9%E9%99%85%E4%BA%A7%E5%87%BA%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20LAM%5B%22%E8%B5%84%E6%9C%AC%E5%BD%B1%E5%AD%90%E4%BB%B7%E5%80%BC%20%CE%BB%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20DISC%5B%22%E6%8A%98%E6%89%A3%E7%8E%87%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20LAM%0A%20%20WAGE%5B%22%E6%95%88%E7%8E%87%E5%B7%A5%E8%B5%84%E6%8A%AC%E9%AB%98%E5%8A%B3%E5%8A%A8%E6%88%90%E6%9C%AC%22%5D%20--%3E%20PROF%5B%22%E6%9C%AA%E6%9D%A5%E5%88%A9%E6%B6%A6%E7%A7%9F%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20LAM%0A%20%20LAM%20--%3E%20Q%5B%22%E8%BE%B9%E9%99%85%20q%20%3D%20%CE%BB%20%2F%20P_K%22%5D%0A%20%20PK%5B%22%E9%87%8D%E7%BD%AE%E6%88%90%E6%9C%AC%20P_K%20%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20Q%0A%20%20Q%20--%3E%20UP%5B%22q%20%E8%B6%8A%E8%BF%87%201%3A%20%E6%89%A9%E6%8A%95%E8%B5%84%22%5D%0A%20%20Q%20--%3E%20DOWN%5B%22q%20%E4%BD%8E%E4%BA%8E%201%3A%20%E5%81%9C%E6%AD%A2%E6%8A%95%E8%B5%84%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">直觉类比：把 \\(q\\) 想成「开分店值不值」——重开一家店要花 100 万，而多开一家的预期利润现值是 120 万，比值 1.2 就开；预期只值 90 万就不开。分子是「赚的」，分母是「装的」。</span></p><p>索洛的 \\(s\\) 把投资钉在当期产出比例上，\\(q\\) 把它钉在资本的跨期影子价格上。需求暂时上升若很快过去，\\(\\lambda\\) 几乎不动，\\(I\\) 不应大动——这与凯恩斯的当期 \\(Y\\) 驱动 \\(I\\) 不同。动物精神只有改了预期利润路径才进 \\(q\\)；把股价噪声直接写成 \\(I\\)，是把平均 \\(Q\\) 的测量误差当成结构。</p><p>开放经济下，外国资本成本进入折扣率；CIP 实证仍在<a href="/quant/irp">量化栏</a>，本课不把 \\(q\\) 写成远期基差。增长模型里的 \\(I\\) 一旦离开外生 \\(s\\)，就要用 \\(q\\) 或欧拉来引导——Ramsey 的消费欧拉与这里的资本欧拉是一对。</p><p><span class="marginnote">边际 \\(q\\) 不可直接看见，平均 \\(Q\\) 可看见。理论用前者，实证常用后者。二者分叉时，先查齐性、税与无形资产，再谈「理论失败」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计投资对 \\(Q\\) 的弹性，不把托宾 \\(q\\) 写成交易策略。调整成本、不可逆与固定成本会改 \\(I(q)\\) 的形状——下一课。金融加速器会让外部融资溢价再乘一层，那是更后的周期课。</p><p>无形资产、垄断租进入证券价值时，平均 \\(Q\\) 可以长期大于 1 而不对应安装更多实物 \\(K\\)。测量误差使 \\(Q\\) 回归看起来「失败」，不一定否定边际 \\(q\\)。MM 与代理冲突改的是企业价值如何在证券间分割，不是取消资本的影子价格。</p><p>后课默认：投资的一阶条件用边际 \\(q\\)；平均 \\(Q\\) 只在 Hayashi 条件下等于它。下一课：凸调整成本如何让 \\(I\\) 有限、让 \\(q\\) 可以离开 1。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>劳动侧摩擦已写完；资本侧用 \\(q\\) 当投资的充分统计。</li><li>边际 \\(q=\\lambda/P_K\\)；\\(q\\gt 1\\) 投，\\(q\\lt 1\\) 停。</li><li>Hayashi：齐性下平均 \\(Q\\) 等于边际 \\(q\\)。</li><li>无调整成本时 \\(q\\) 被钉在 1，投资跳——下一课的刀刃。</li><li>出处：Tobin, <em>JMCB</em> 1969；Hayashi, <em>Econometrica</em> 1982。</li></ul>',10))])}const b=s(q,[["render",p]]);export{C as __pageData,b as default};
